package org.racedaydreams.data;
import android.test.AndroidTestCase;
import android.database.sqlite.SQLiteDatabase;
import java.time.*;
import java.util.*;
import org.json.*;
import org.racedaydreams.domain.strength.*;
import org.racedaydreams.domain.coaching.Immutable;
/** Real SQLite/JSON round trips, legacy compatibility and transactional failure preservation. */
public final class StrengthReleaseStoreTest extends AndroidTestCase {
    private FeatureStore features;private CoachingStore coach;private StrengthUserStore choices;private GymProgrammeStore gym;
    @Override protected void setUp()throws Exception{super.setUp();new SqliteUserPreferencesRepository(getContext()).clear();features=new FeatureStore(getContext());coach=new CoachingStore(getContext());choices=new StrengthUserStore(getContext());gym=new GymProgrammeStore(getContext());}
    @Override protected void tearDown()throws Exception{new SqliteUserPreferencesRepository(getContext()).clear();super.tearDown();}
    public void testTimedAndDistanceSetsRetainMeasurementsAfterBackup(){var plank=ExerciseCatalog.definition("plank").exercise();var carry=ExerciseCatalog.definition("farmers-carry").exercise();var session=new StrengthSession("s",Instant.now().minusSeconds(3600),ZoneOffset.UTC,Duration.ofMinutes(30),6.0,"",Immutable.list(new StrengthSession.ExerciseSets(plank,Immutable.list(new StrengthSession.SetEntry("a",0,0,null,false,135L,null))),new StrengthSession.ExerciseSets(carry,Immutable.list(new StrengthSession.SetEntry("b",0,40,7.0,false,null,60.0)))));coach.saveStrength(session);assertEquals(session,coach.strength().get(0));features.restoreUserData(features.exportUserData(),false);assertEquals(session,coach.strength().get(0));assertEquals(2,StrengthAnalytics.progression(coach.strength()).size());}
    public void testFavouritesArchiveAndAcknowledgementsSurviveRestore(){choices.save(new StrengthUserStore.Choice("back-squat",true,true));choices.acknowledge("strength:pb");var b=features.exportUserData();choices.save(new StrengthUserStore.Choice("back-squat",false,false));features.restoreUserData(b,false);assertTrue(choices.choices().get(0).favourite());assertTrue(choices.choices().get(0).archived());assertTrue(choices.acknowledged().contains("strength:pb"));}
    public void testLegacySamsungBackupNormalizesPreferenceWithoutLosingManualData()throws Exception{JSONObject b=features.exportUserData();b.remove("strengthState");b.remove("gymProgramming");b.getJSONObject("settings").put("provider.preference","SAMSUNG_EXPERIMENTAL");features.restoreUserData(b,false);assertEquals("HEALTH_CONNECT",features.getSetting("provider.preference"));assertTrue(choices.choices().isEmpty());}
    public void testV5MigrationPreservesPayloadAndNormalizesPreference()throws Exception{new SqliteUserPreferencesRepository(getContext()).clear();try(SQLiteDatabase db=getContext().openOrCreateDatabase(ProfileDatabase.NAME,0,null)){for(String name:new String[]{"createVersionOne","migrateOneToTwo","migrateTwoToThree","migrateThreeToFour","migrateFourToFive"}){var m=ProfileDatabase.class.getDeclaredMethod(name,SQLiteDatabase.class);m.setAccessible(true);m.invoke(null,db);}db.execSQL("INSERT INTO settings VALUES ('provider.preference','SAMSUNG_EXPERIMENTAL')");db.execSQL("INSERT INTO settings VALUES ('calendar.view','Month')");db.setVersion(5);}assertEquals("HEALTH_CONNECT",features.getSetting("provider.preference"));assertEquals("Month",features.getSetting("calendar.view"));assertTrue(choices.choices().isEmpty());}
    private GymProgramme plan(){var s=new GymProgramme.Settings(GymProgramme.Goal.SUPPORT_RUNNING,GymProgramme.Priority.RUNNING_FIRST,GymProgramme.Experience.BEGINNER,EnumSet.of(DayOfWeek.TUESDAY,DayOfWeek.FRIDAY),2,Immutable.set("bodyweight"),30,GymProgramme.Effort.RIR);return new GymProgrammeGenerator().generate("p",1,Instant.now(),"Runner approved",s,LocalDate.now(),Immutable.list(),Immutable.list());}
    public void testImmutableGymVersionHistoryAndStopSurviveBackup(){var p=plan();gym.save(p);var session=p.sessions().get(0);var changed=GymPlanEditor.reduce(p,session.id(),LocalDate.now(),Instant.now(),Immutable.set());gym.save(changed);assertEquals(2,gym.versions().size());assertEquals(p,gym.versions().get(1));features.restoreUserData(features.exportUserData(),false);assertEquals(changed,gym.current());gym.disable();features.restoreUserData(features.exportUserData(),false);assertNull(gym.current());assertEquals(2,gym.versions().size());}
    public void testInvalidGymBackupRetainsCurrentData()throws Exception{gym.save(plan());choices.save(new StrengthUserStore.Choice("back-squat",true,false));var backup=features.exportUserData();backup.getJSONObject("gymProgramming").put("current","missing:v99");try{features.restoreUserData(backup,false);fail("Missing current reference accepted");}catch(IllegalArgumentException expected){}assertNotNull(gym.current());assertTrue(choices.choices().get(0).favourite());}
    public void testActualGymLinkRetainsOriginalVersionOnRoundTrip(){var p=plan();gym.save(p);var s=p.sessions().get(0);var development=new DevelopmentStore(getContext());coach.saveStrength(new StrengthSession("actual",Instant.now().minusSeconds(3600),ZoneOffset.UTC,Duration.ofMinutes(30),null,"",Immutable.list(new StrengthSession.ExerciseSets(ExerciseCatalog.definition("back-squat").exercise(),Immutable.list(new StrengthSession.SetEntry("a",5,80,7.0,false))))));development.linkGym("actual",s.date(),GymProgrammeStore.key(p),s.id());features.restoreUserData(features.exportUserData(),false);assertEquals(GymProgrammeStore.key(p),development.gymLinks().get("actual").versionKey());assertEquals(s.id(),development.gymLinks().get("actual").prescribedSessionId());}
    public void testRawRirSurvivesStorageAndBackup(){var e=ExerciseCatalog.definition("back-squat").exercise();var set=new StrengthSession.SetEntry("rir",5,80,null,false,null,null,3.0);var session=new StrengthSession("rir-session",Instant.now().minusSeconds(3600),ZoneOffset.UTC,Duration.ofMinutes(30),null,"",Immutable.list(new StrengthSession.ExerciseSets(e,Immutable.list(set))));coach.saveStrength(session);features.restoreUserData(features.exportUserData(),false);assertEquals(set,coach.strength().get(0).exercises().get(0).sets().get(0));assertNull(coach.strength().get(0).exercises().get(0).sets().get(0).rpe());}
    public void testManualTimedPbCanBeEditedAndDeleted(){var e=ExerciseCatalog.definition("plank").exercise();var d=new DevelopmentStore(getContext());d.saveHistorical(new HistoricalStrengthRecord("h",e,0,0,null,HistoricalStrengthRecord.DatePrecision.UNKNOWN,"",60L,null));d.saveHistorical(new HistoricalStrengthRecord("h",e,0,0,null,HistoricalStrengthRecord.DatePrecision.UNKNOWN,"Corrected",90L,null));assertEquals(Long.valueOf(90),d.historical().get(0).durationSeconds());features.restoreUserData(features.exportUserData(),false);assertEquals(Long.valueOf(90),d.historical().get(0).durationSeconds());d.deleteHistorical("h");assertTrue(d.historical().isEmpty());}
}
